# Judge's variant of AC d02 (not blind): the excluded line is put back at its reader-file position (P11b satisfied)
# and the phrase is regenerated by `check_claims.py --generate`'s template, so only P12 can catch it.
import os, subprocess, sys
root = sys.argv[1]
def sub(path, old, new):
    p = os.path.join(root, path); s = open(p, encoding="utf-8").read()
    assert s.count(old) == 1, (path, old); open(p, "w", encoding="utf-8").write(s.replace(old, new))
line = "CLAUSE | Checked.Chemistry.Coexistence.IsMaxwellCoexistence | equivalent to equal chemical potential in both phases"
sub("scripts/trust/phrase_clause_baseline.txt", line + "\n", "")
a = "CLAUSE | Checked.Chemistry.Coexistence.IsMaxwellCoexistence | equal areas between the isotherm and the saturation pressure line\n"
sub("scripts/trust/phrase_roles.txt", a, a + line + "\n")
sub("scripts/trust/phrases.txt", "saturation pressure line; pressure is a function",
    "saturation pressure line; equivalent to equal chemical potential in both phases; pressure is a function")
open(os.path.join(root, "LEDGER.md"), "a", encoding="utf-8").write("\n- IsMaxwellCoexistence: phrase regenerated.\n")
